<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { useUserStore } from '@vben/stores';import { ElButton,ElSkeleton } from 'element-plus';import { requestClient } from '#/api/request';import DataErrorBanner from '#/components/data-state/DataErrorBanner.vue';import OperationsChart from './OperationsChart.vue';import TherapyFunnelCard from './TherapyFunnelCard.vue';
const props=defineProps<{analytics?:boolean}>();const router=useRouter(),user=useUserStore();
type Item={name:string;value:number};type Overview={totals:Record<string,number>;daily:Array<{date:string;users:number;works:number;sessions:number;finished:number}>;categories:Item[];projectStates:Item[];sessionStates:Item[];programKinds:Item[];bookingStates:Item[];generatedAt:string};
const data=ref<Overview|null>(null),days=ref(7),loading=ref(false),error=ref('');let generation=0;
const isAdmin=computed(()=>user.userInfo?.roles?.includes('ROLE_3'));const nickname=computed(()=>user.userInfo?.realName||'工作伙伴');
const cards=[{key:'users',label:'平台用户',caption:'全部已注册用户',icon:'◎',path:'/zhiyu/business/users'},{key:'sessions',label:'创作会话',caption:'累计开始的创作',icon:'◷',path:'/zhiyu/data-center/analytics'},{key:'works',label:'创作作品',caption:'全部作品记录',icon:'▧',path:'/zhiyu/business/works'},{key:'projects',label:'已上架项目',caption:'当前可体验内容',icon:'⌘',path:'/zhiyu/business/audit'}];
async function load(){const turn=++generation;loading.value=true;error.value='';try{const result=await requestClient.get<Overview>('/admin/dashboard/operations',{params:{days:days.value}});if(turn===generation)data.value=result}catch{if(turn===generation){error.value='运营数据暂未读取成功，请确认后端与数据库迁移后重试。'}}finally{if(turn===generation)loading.value=false}}
function range(n:number){days.value=n;load()}onMounted(()=>{if(isAdmin.value)load()});
const date=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'}).format(new Date());
</script>
<template><main class="operations">
 <header class="op-top"><div><p class="overline">ZHIYU / {{analytics?'INSIGHTS':'WORKSPACE'}}</p><h1>{{analytics?'每一份参与，都清晰可见。':`你好，${nickname}`}}</h1><p class="lede">{{analytics?'从内容供给到创作参与，了解平台正在发生什么。':'把日常事务安排好，让创作与关怀慢慢发生。'}}</p></div><div class="top-right"><span>{{date}}</span><ElButton v-if="isAdmin" :loading="loading" @click="load">↻ 刷新数据</ElButton></div></header>
 <template v-if="isAdmin">
 <DataErrorBanner
  v-if="error"
  :error="error"
  :retrying="loading"
  @retry="load"
 />
 <section v-if="!analytics" class="task-panel priority-panel"><p class="overline">NEEDS ATTENTION</p><h3>今天，优先处理</h3><button @click="router.push('/zhiyu/business/audit')"><span><b>内容审核</b><small>让新的手作与大家见面</small></span><strong>{{data?.totals.pending??'—'}}</strong><span>→</span></button><button @click="router.push('/zhiyu/business/care-reminders')"><span><b>关怀提醒</b><small>仅查看授权的脱敏信息</small></span><strong>{{data?.totals.care??'—'}}</strong><span>→</span></button><button @click="router.push('/zhiyu/programs')"><span><b>预约处理</b><small>确认申请，安排下一次相见</small></span><span>→</span></button></section>
 <section v-if="!analytics" class="welcome-strip"><div><span class="strip-label">让每一次开始，都有人回应</span><h2>今天，从一件值得做的小事开始。</h2><p>查看待办，整理内容，为下一次手作留好位置。</p><button @click="router.push('/zhiyu/programs')">安排活动与预约 <span>↗</span></button></div><img src="/weave-scene.svg" alt="交织的纸带与叶形纹样"/></section>
 <section class="op-metrics"><button v-for="(card,i) in cards" :key="card.key" @click="router.push(card.path)"><div class="metric-top"><span>{{card.label}}</span><span class="metric-icon" :class="'tone-'+i">{{card.icon}}</span></div><strong>{{data?Number(data.totals[card.key]).toLocaleString():'—'}}</strong><div class="metric-bottom"><span>{{card.caption}}</span><span>↗</span></div></button></section>
 <div class="section-heading"><div><h2>{{analytics?'参与趋势与内容结构':'运营概览'}}</h2><span>趋势按北京时间自然日统计 · 分布为当前全部记录</span></div><div class="range"><button v-for="n in [7,30]" :key="n" :class="{selected:days===n}" :aria-pressed="days===n" @click="range(n)">近 {{n}} 天</button></div></div>
 <TherapyFunnelCard v-if="!analytics" :days="days"/>
 <ElSkeleton v-if="loading&&!data" :rows="5" animated/>
 <template v-else-if="data">
 <div class="charts-top"><OperationsChart title="创作与参与趋势" :subtitle="`近 ${days} 天 · 可点击图例筛选；各曲线按各自发生日期统计`" kind="line" :rows="data?.daily||[]" empty-text="暂无创作趋势" :empty-hint="`近 ${days} 天还没有创作记录`"/><OperationsChart title="创作进行到哪一步" subtitle="全部创作会话状态分布" kind="pie" :rows="data?.sessionStates||[]" empty-text="暂无创作会话" empty-hint="完成一次创作后会在这里显示状态分布"/></div>
 <div class="charts-bottom" :class="{overview:!analytics}"><OperationsChart drilldown @select="row=>router.push({path:'/zhiyu/business/audit',query:{status:'1',category:row.name}})" title="手作内容分布" subtitle="已上架项目 · 数量前 12 个分类" kind="bar" :rows="data?.categories||[]" empty-text="暂无已上架项目" empty-hint="上架手作内容后会在这里显示分类分布"/><OperationsChart drilldown @select="row=>router.push({path:'/zhiyu/business/audit',query:{status:({'待审核':'0','待审':'0','已上架':'1','上架':'1','已下架':'2','下架':'2'} as Record<string,string>)[row.name]||'0'}})" title="内容上架进度" subtitle="项目审核与发布状态" kind="pie" :rows="data?.projectStates||[]" empty-text="暂无审核记录" empty-hint="提交项目审核后会在这里显示进度"/><OperationsChart v-if="analytics" title="预约与签到" subtitle="全部报名记录 · 含已取消" kind="bar" :rows="data?.bookingStates||[]" empty-text="暂无报名记录" empty-hint="产生报名后会在这里显示签到状态"/></div>
 <div v-if="analytics" class="charts-top"><OperationsChart drilldown @select="row=>router.push({path:'/zhiyu/programs',query:{kind:({'工作坊':'WORKSHOP','主题工作坊':'WORKSHOP','课程':'COURSE','系列课程':'COURSE','一对一':'GUIDANCE','一对一指导':'GUIDANCE','个别指导':'GUIDANCE'} as Record<string,string>)[row.name]||row.name}})" title="活动内容供给" subtitle="当前已发布活动 · 按类型" kind="bar" :rows="data?.programKinds||[]" empty-text="暂无已发布活动" empty-hint="发布活动后会在这里显示类型分布"/><section class="method-panel"><p class="overline">ABOUT THE DATA</p><h3>真实记录，清晰边界</h3><p>曲线中的“开始”和“完成”分别按开始日、完成日计数，不能直接相除得到同一批用户的完成率。</p><p>零值意味着该日期没有记录；空图意味着尚无相关数据。逻辑删除的记录不计入统计。</p><p>参与次数与作品数量不代表心理改善或临床疗效。</p></section></div>
 </template>
 <p class="updated">{{data?'数据更新于 '+new Date(data.generatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'等待真实数据'}} · 本系统不能替代专业心理咨询</p>
 </template><section v-else class="method-panel"><h2>欢迎回到织愈工作空间</h2><p>在你的授权范围内维护内容、安排课程与活动。</p><ElButton type="primary" @click="router.push('/zhiyu/programs')">进入活动与预约</ElButton><p>本系统不能替代专业心理咨询</p></section>
</main></template>
<style scoped>
.priority-panel{display:grid;grid-template-columns:1fr repeat(3,minmax(0,1fr));align-items:center;gap:24px;margin-bottom:24px}.priority-panel>.overline{display:none}.priority-panel button{border:0;padding:12px 0}.charts-bottom.overview{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:1000px){.priority-panel{grid-template-columns:repeat(3,minmax(0,1fr))}.priority-panel h3{grid-column:1/-1;margin:0}}@media(max-width:720px){.priority-panel{grid-template-columns:1fr;gap:4px}.priority-panel button{border-bottom:1px solid var(--op-border)}.charts-bottom.overview{grid-template-columns:1fr}}

.operations{--op-card: var(--el-bg-color);--op-border: var(--el-border-color);--op-text: var(--el-text-color-primary);--op-muted: var(--el-text-color-regular);padding:30px 34px;background: var(--el-bg-color-page);min-height:100%;color:var(--op-text)}.op-top{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:28px}.overline{font-size:11px;font-weight:650;letter-spacing:2.8px;color: var(--el-text-color-regular);margin-bottom:12px}.op-top h1{font-size:30px;font-weight:650;letter-spacing:-.8px}.lede{font-size:13px;color:var(--op-muted);margin-top:10px}.top-right{display:flex;align-items:center;gap:18px;font-size:12px;color:var(--op-muted)}.welcome-strip{display:flex;justify-content:space-between;overflow:hidden;position:relative;background: var(--el-color-primary-light-9);border: 1px solid var(--el-color-primary-light-8);border-radius:22px;padding:30px 36px;margin-bottom:24px;color: var(--el-text-color-primary)}.welcome-strip>div{z-index:1}.strip-label{font-size:11px;letter-spacing:2px;color: var(--el-text-color-regular)}.welcome-strip h2{font-size:25px;margin:14px 0 10px;font-weight:550}.welcome-strip p{font-size:13px;color: var(--el-text-color-regular)}.welcome-strip button{display:flex;gap:40px;background: var(--el-color-primary);color: var(--el-color-white);border-radius:9px;padding:12px 18px;margin-top:20px;font-size:12px}.welcome-strip img{position:absolute;right:0;top:-40px;width:420px;height:280px;opacity:.9;pointer-events:none}.op-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:24px 0 30px}.op-metrics>button{text-align:left;background:var(--op-card);border:1px solid var(--op-border);border-radius:18px;padding:20px 24px;transition:transform .18s}.op-metrics>button:hover{transform:translateY(-3px)}.metric-top,.metric-bottom{display:flex;align-items:center;justify-content:space-between;color:var(--op-muted);font-size:12px}.metric-icon{display:grid;place-items:center;width:34px;height:34px;background: var(--el-color-primary-light-9);color: var(--el-color-primary);border-radius:10px;font-size:23px}.tone-1{background: var(--el-color-warning-light-9);color: var(--el-color-warning)}.tone-2{background: var(--el-color-info-light-9);color: var(--el-color-info)}.tone-3{background: var(--el-color-success-light-9);color: var(--el-color-success)}.op-metrics strong{font-size:36px;font-weight:600;display:block;letter-spacing:-1px;margin:6px 0 12px}.metric-bottom{font-size:11px}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:28px 0 18px;gap:20px}.section-heading h2{font-size:19px;font-weight:600;margin-bottom:7px}.section-heading span{font-size:11px;color:var(--op-muted)}.range{display:flex;background:var(--op-card);padding:4px;border:1px solid var(--op-border);border-radius:10px;gap:4px}.range button{padding:8px 14px;font-size:12px;border-radius:7px;white-space:nowrap}.range .selected{background: var(--el-color-primary);color: var(--el-color-white)}.charts-top{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(0,1fr);gap:20px;margin-bottom:20px}.charts-bottom{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-bottom:20px}.task-panel,.method-panel{background:var(--op-card);border:1px solid var(--op-border);border-radius:20px;padding:24px;min-width:0}.task-panel h3,.method-panel h3{font-size:18px;font-weight:600;margin:12px 0 16px}.task-panel button{display:flex;width:100%;align-items:center;justify-content:space-between;gap:12px;text-align:left;padding:20px 0;border-bottom:1px solid var(--op-border);font-size:12px}.task-panel b{font-weight:550}.task-panel small{display:block;font-size:11px;color:var(--op-muted);margin-top:8px}.task-panel strong{font-size:26px;font-weight:550}.method-panel p{font-size:13px;line-height:2;color:var(--op-muted);margin:18px 0}.updated{text-align:center;margin-top:28px;font-size:12px;color:var(--op-muted)}button:focus-visible{outline: 3px solid var(--el-color-primary);outline-offset:3px}@media(max-width:1100px){.charts-bottom{grid-template-columns:repeat(2,minmax(0,1fr))}.welcome-strip img{opacity:.3}.top-right>span{display:none}}@media(max-width:720px){.operations{padding:20px 16px}.op-top{align-items:flex-start}.op-top h1{font-size:24px}.welcome-strip{padding:24px}.welcome-strip h2{font-size:20px}.op-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.op-metrics>button{padding:18px}.charts-top,.charts-bottom{grid-template-columns:1fr}.section-heading{align-items:flex-start}.section-heading span{display:none}.op-top .lede{max-width:230px}.top-right{padding-top:24px}}@media(prefers-reduced-motion:reduce){.op-metrics>button{transition:none}.op-metrics>button:hover{transform:none}}
</style>
